import subprocess,json
from pathlib import Path
root=Path('/root/sidereal_spacetime');out=root/'output/playwright/planet-reference-20260914/shadow-followup'
code='''async(page)=>{for(const mode of ['depth-offset','backface-culled']){const data=await page.evaluate(mode=>{const r=window.planetReview;r.scene.shadowsEnabled=true;let stats=[];for(const l of r.scene.lights){const s=l.getShadowGenerator();if(s){s.usePercentageCloserFiltering=true;s.normalBias=0;s.bias=mode==='depth-offset'?.01:.0005;s.forceBackFacesOnly=mode==='backface-culled';for(const m of s.getShadowMap().renderList){if(mode==='backface-culled')m.material.backFaceCulling=true;stats.push({name:m.name,doubleSided:!m.material.backFaceCulling});}}}r.scene.render();return stats},mode);await page.waitForTimeout(500);await page.evaluate(()=>{window.planetReview.scene.render();window.planetReview.scene.render()});await page.screenshot({path:OUT+'/ice-'+mode+'.png'});}}'''.replace('OUT',json.dumps(str(out)))
p=subprocess.run(['bash',str(root/'.agents/skills/playwright/scripts/playwright_cli.sh'),'-s=planet-art-recovery','run-code',code],capture_output=True,text=True);(out/'caster-probe.log').write_text(p.stdout+p.stderr);p.check_returncode()
